INSERT INTO COMMENT_MANAGEMENT ( /* commentMapper.insertComment (댓글 등록)*/
            BOARD_ID
          , MEMBER_ID
          , USER_ID
          , CONTENT
          , PARENT_COMMENT_ID
          , LIKE_COUNT
          , CREATE_AT
          , UPDATE_AT
          , DELETE_YN
)    VALUES (
            #{boardId}
          , #{memberId}
          , #{userId}
          , #{content}
          , #{parentCommentId}
          , 0
          , NOW()
          , NOW()
          , 'N'
)

