UPDATE comment_management /* CommentMapper.updateComment (댓글 내용 수정) */
   SET CONTENT = #{content}
     , UPDATE_AT = NOW()
 WHERE COMMENT_ID = #{commentId}

UPDATE COMMENT_MANAGEMENT /* CommentMapper.deleteComment (자식이 있는 경우, 댓글삭제, '삭제된 댓글입니다' 로 마스킹 진행) */
